package com.aoo.bcg.gamespi.fsm;
import java.util.*;import java.util.concurrent.atomic.AtomicInteger;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class TerminalStateIrreversibilityTest{enum Event{LATE_COMMAND}@Test void terminalStateRejectsEveryLateEventWithoutMutation(){var table=new StateTransitionTable<RoomLifecycleState,Event>(List.of(),Set.of(RoomLifecycleState.FINISHED,RoomLifecycleState.DISSOLVED));var effects=new AtomicInteger();for(var state:List.of(RoomLifecycleState.FINISHED,RoomLifecycleState.DISSOLVED)){var result=table.tryTransition(state,Event.LATE_COMMAND,name->true,name->effects.incrementAndGet());assertEquals("TERMINAL_STATE",result.code());assertEquals(state,result.state());}assertEquals(0,effects.get());assertThrows(IllegalArgumentException.class,()->new StateTransitionTable<>(List.of(new StateTransition<>(RoomLifecycleState.FINISHED,Event.LATE_COMMAND,RoomLifecycleState.PLAYING,"always","mutate")),Set.of(RoomLifecycleState.FINISHED)));}}
